"""Stage 7: compare every model on one split with intervals and paired tests. --split test is one gated test read."""
import argparse, json
import joblib, numpy as np, pandas as pd
from scipy.stats import binomtest
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import common as C

BASE = ["hgb", "nb", "gmm", "tree", "logreg", "perceptron", "knn"]
BASE_FS = ["selected", "shape16", "colour90", "all106"]
NBOOT = 2000


def model_list():
    """(model, featureset, seeds) for everything that can be scored."""
    L = [(m, fs, (0,)) for fs in BASE_FS for m in BASE] + [("nb", "distinct91", (0,))]
    return L + [("tree4", "all106", (0,)), ("mlp", "all106", C.SEEDS), ("cnn", "image", C.SEEDS)]


def model_file(m, fs, k):
    """The saved file behind one model and seed; test_probs and the preflight both use it."""
    if m in ("cnn", "mlp"): return C.MODELS / f"{m}_seed{k}.pt"
    return C.MODELS / "baselines" / f"{m}__{fs}.joblib"


def read_needs():
    """Every file the test path loads, built from model_list so the two cannot drift."""
    return [model_file(m, fs, k) for m, fs, seeds in model_list() for k in seeds] + [C.MODELS / "mlp_prep.joblib", C.cache_path()]


def preflight(paths):
    """Names everything missing and stops, before a test read is spent."""
    gone = [str(p) for p in paths if not p.exists()]
    if gone: raise SystemExit("cannot read test, missing:\n  " + "\n  ".join(gone))


def test_probs(df, m, fs, k):
    """Test-split probabilities from a saved model."""
    if m == "cnn": return C.cnn_on_df(model_file(m, fs, k), df)[0]
    if m == "mlp": return C.mlp_probs(model_file(m, fs, k), df[C.ALL106].to_numpy(np.float64))
    obj = joblib.load(model_file(m, fs, k))
    return obj["pipe"].predict_proba(df[obj["cols"]])


def score_models(df):
    """Every model on the read rows. A model that cannot load stops the stage: dropping it would spend the read on part of the study."""
    preds = {}
    for m, fs, seeds in model_list():
        for k in seeds:
            C.save_preds(m, fs, k, "test", df.grain_id, df.y, test_probs(df, m, fs, k))
            preds[(m, fs, k)] = C.load_preds(m, fs, k, "test")
    return preds


def paired(oka, okb, idx):
    """b, c, exact two-sided binomial p and bootstrap accuracy differences for two aligned right-or-wrong arrays."""
    b = int((oka & ~okb).sum()); c = int((~oka & okb).sum())
    p = binomtest(min(b, c), b + c, 0.5).pvalue if b + c else 1.0
    return b, c, p, oka[idx].mean(1) - okb[idx].mean(1)


def boot_f1(y, pred, idx):
    out = np.empty(len(idx))
    for i, ix in enumerate(idx):
        yt, yp = y[ix], pred[ix]
        f = []
        for c in range(5):
            tp = np.sum((yt == c) & (yp == c)); fp = np.sum((yt != c) & (yp == c)); fn = np.sum((yt == c) & (yp != c))
            f.append(2 * tp / max(2 * tp + fp + fn, 1))
        out[i] = np.mean(f)
    return out


def holm(p):
    o = np.argsort(p)
    adj = np.empty(len(p))
    run = 0.0
    for r, i in enumerate(o):
        run = max(run, (len(p) - r) * p[i])
        adj[i] = min(1.0, run)
    return adj


def lot_rows(y, pred, cls, lots):
    """Recall per class and lot on validation rows, so a gap between lots cannot hide in the pooled score. Late is Jasmine only, so macro F1 would mean nothing there."""
    r = []
    for (m, fs, k), p in pred.items():
        for c, l in sorted(set(zip(cls, lots))):
            i = (cls == c) & (lots == l)
            r.append({"model": m, "featureset": fs, "seed": k, "class": c, "lot": l, "n": int(i.sum()), "recall": float((p[i] == y[i]).mean()), "errors": int((p[i] != y[i]).sum())})
    return r


def angle_rows(y, pred, deg):
    """Scores per grain-angle band on validation rows, every band and class listed even when empty. Class 'all' pools the band; its macro_f1 averages the classes with rows
    in that band, so an absent class does not count as 0. A class row is that class inside the band: accuracy is its recall, f1 its F1 against the band's other rows."""
    from sklearn.metrics import f1_score
    band, r = C.angle_band(deg), []
    grid = [(f"{lo}-{hi}", lo, hi) for lo, hi in C.ANGLE_BANDS] + [(C.NO_ANGLE, np.nan, np.nan)]
    for (m, fs, k), p in pred.items():
        for b, lo, hi in grid:
            i = band == b
            yb, pb, per = y[i], p[i], []
            for t, c in enumerate(C.CLASSES):
                j = yb == t
                per.append({"class": c, "n": int(j.sum()), "accuracy": float((pb[j] == t).mean()) if j.any() else np.nan, "macro_f1": np.nan,
                            "f1": float(f1_score(j, pb == t, zero_division=0)) if j.any() else np.nan, "errors": int((pb[j] != t).sum())})
            have = [q["f1"] for q in per if q["n"]]
            every = {"class": "all", "n": int(i.sum()), "accuracy": float((pb == yb).mean()) if i.any() else np.nan, "macro_f1": float(np.mean(have)) if have else np.nan,
                     "f1": np.nan, "errors": int((pb != yb).sum())}
            r += [{"model": m, "featureset": fs, "seed": k, "band": b, "lo_deg": lo, "hi_deg": hi} | q for q in [every] + per]
    return r


def angle_lot_rows(y, pred, deg, cls, lots):
    """Recall per grain-angle band, class and lot on validation rows, so a band gap inside one lot cannot hide in the pooled band. Every band is listed for every class and lot
    pair the rows hold, even when empty, and n is the rows behind the cell. Recall only, as in lot_rows: late is Jasmine only, so macro F1 would mean nothing there."""
    band, r = C.angle_band(deg), []
    grid = [(f"{lo}-{hi}", lo, hi) for lo, hi in C.ANGLE_BANDS] + [(C.NO_ANGLE, np.nan, np.nan)]
    for (m, fs, k), p in pred.items():
        for b, lo, hi in grid:
            for c, l in sorted(set(zip(cls, lots))):
                i = (band == b) & (cls == c) & (lots == l)
                r.append({"model": m, "featureset": fs, "seed": k, "band": b, "lo_deg": lo, "hi_deg": hi, "class": c, "lot": l, "n": int(i.sum()),
                          "recall": float((p[i] == y[i]).mean()) if i.any() else np.nan, "errors": int((p[i] != y[i]).sum())})
    return r


def read_test():
    """The single gated test read of this stage. An infinite cell becomes a missing one, which every pipeline imputes; left in, the first imputer raises right after the read."""
    df = C.load_split("test")
    print(f"test read: {len(df)} grains, {int(np.isinf(df[C.ALL106].to_numpy(np.float64)).sum())} infinite cells made missing", flush=True)
    return df.replace([np.inf, -np.inf], np.nan)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--split", choices=["val", "test"], default="test")
    a = ap.parse_args()
    out = C.stage_dir("compare")
    sp = a.split
    preds, rows = {}, None
    if sp == "test":
        preflight(read_needs())            # names every missing file before the read is spent
        rows = read_test()
        preds = score_models(rows)
    else:
        for m, fs, seeds in model_list():
            for k in seeds:
                d = C.load_preds(m, fs, k, "val")
                if d is not None: preds[(m, fs, k)] = d
    assert preds, "no predictions found"
    tables(preds, sp, out, rows)


def tables(preds, sp, out, rows=None):
    """Everything after the predictions. Apart from main so a test can drive the real tables on made-up predictions. `rows` is the frame of the grains scored: the read's own frame for test (load_grains has no test rows, a second load_split would log a second read); validation uses load_grains."""
    ref = next(iter(preds.values()))
    ids = ref.grain_id.to_numpy()
    y = ref.y.to_numpy().astype(int)
    for key, d in preds.items():
        assert (d.grain_id.to_numpy() == ids).all(), f"grain order differs for {key}"
    n = len(y)
    rng = np.random.default_rng(C.SEED)
    idx = rng.integers(0, n, (NBOOT, n))       # one set of resamples shared by every model (paired)
    pred = {k: C.probs(d).argmax(1) for k, d in preds.items()}
    ok = {k: (p == y) for k, p in pred.items()}
    mrows, rec, cm = [], [], []
    for k, p in pred.items():
        m, fs, s = k
        acc_b = ok[k][idx].mean(1)
        f1_b = boot_f1(y, p, idx)
        mrows.append(dict(model=m, featureset=fs, seed=s, split=sp, n=n, accuracy=ok[k].mean(), errors=int((~ok[k]).sum()),
                         acc_lo=np.percentile(acc_b, 2.5), acc_hi=np.percentile(acc_b, 97.5), macro_f1=C.macro_f1(y, p),
                         macro_precision=C.macro_precision(y, p), macro_recall=C.macro_recall(y, p),
                         f1_lo=np.percentile(f1_b, 2.5), f1_hi=np.percentile(f1_b, 97.5)))
        for c in range(5):
            tp, fp, fn = int(((y == c) & (p == c)).sum()), int(((y != c) & (p == c)).sum()), int(((y == c) & (p != c)).sum())
            prec = tp / (tp + fp) if tp + fp else 0.0
            rc = tp / (tp + fn) if tp + fn else 0.0
            rec.append(dict(model=m, featureset=fs, seed=s, split=sp, **{"class": C.CLASSES[c]}, n=int((y == c).sum()),
                            recall=float(rc), precision=float(prec), f1=float(2 * prec * rc / (prec + rc)) if prec + rc else 0.0,
                            errors=int((p[y == c] != c).sum())))
        for t in range(5):
            for q in range(5):
                cm.append(dict(model=m, featureset=fs, seed=s, true=C.CLASSES[t], predicted=C.CLASSES[q], count=int(((y == t) & (p == q)).sum())))
    M = pd.DataFrame(mrows)
    M.to_csv(out / f"{sp}_metrics.csv", index=False); C.wrote(out / f"{sp}_metrics.csv")
    pd.DataFrame(rec).to_csv(out / f"{sp}_recall.csv", index=False); C.wrote(out / f"{sp}_recall.csv")
    if sp == "val" or rows is not None:
        vg = (C.load_grains() if rows is None else rows).set_index("grain_id").reindex(ref.grain_id)
        assert vg["class"].notna().all(), "predictions hold grains that the rows do not"
        pd.DataFrame(lot_rows(y, pred, vg["class"].to_numpy(), vg["lot"].to_numpy())).to_csv(out / f"{sp}_by_lot.csv", index=False); C.wrote(out / f"{sp}_by_lot.csv")
        deg = C.angles(vg)
        pd.DataFrame(angle_rows(y, pred, deg)).to_csv(out / f"{sp}_by_angle.csv", index=False); C.wrote(out / f"{sp}_by_angle.csv")
        pd.DataFrame(angle_lot_rows(y, pred, deg, vg["class"].to_numpy(), vg["lot"].to_numpy())).to_csv(out / f"{sp}_by_angle_lot.csv", index=False); C.wrote(out / f"{sp}_by_angle_lot.csv")
    pd.DataFrame(cm).to_csv(out / f"{sp}_confusion.csv", index=False); C.wrote(out / f"{sp}_confusion.csv")
    sd = M.groupby(["model", "featureset"]).agg(seeds=("seed", "size"), acc_mean=("accuracy", "mean"), acc_sd=("accuracy", "std"),
                                                  f1_mean=("macro_f1", "mean"), f1_sd=("macro_f1", "std"), err_min=("errors", "min"), err_max=("errors", "max")).reset_index()
    sd.to_csv(out / f"{sp}_seed_spread.csv", index=False); C.wrote(out / f"{sp}_seed_spread.csv")

    # paired tests: seed 0 is the primary family, seeds 1 and 2 are a check
    def get(spec, s):
        m, fs = spec.split(":")
        return (m, fs, s if m in ("cnn", "mlp") else 0)
    tests = []
    for s in C.SEEDS:
        for A, B in C.PAIRS:
            ka, kb = get(A, s), get(B, s)
            if ka not in ok or kb not in ok: continue
            b, c, p, diff = paired(ok[ka], ok[kb], idx)
            tests.append(dict(seed=s, model_a=A, model_b=B, b_a_right_b_wrong=b, c_a_wrong_b_right=c, disagreements=b + c, p_exact=p,
                              errors_a=int((~ok[ka]).sum()), errors_b=int((~ok[kb]).sum()), acc_diff=float(ok[ka].mean() - ok[kb].mean()),
                              diff_lo=np.percentile(diff, 2.5), diff_hi=np.percentile(diff, 97.5), family="primary" if s == 0 else "seed_check"))
    T = pd.DataFrame(tests)
    if len(T):
        T["p_holm"] = np.nan
        for s in T.seed.unique():
            i = T.index[T.seed == s]
            T.loc[i, "p_holm"] = holm(T.loc[i, "p_exact"].to_numpy())
    T.to_csv(out / f"{sp}_mcnemar.csv", index=False); C.wrote(out / f"{sp}_mcnemar.csv")
    print(M[M.seed == 0][["model", "featureset", "accuracy", "errors", "macro_f1"]].round(5).to_string(index=False))
    print(T.round(5).to_string(index=False))

    prim = [k for k in [("hgb", "all106", 0), ("cnn", "image", 0), ("mlp", "all106", 0)] if k in ok]
    fig, axs = plt.subplots(1, len(prim), figsize=(4.2 * len(prim), 4), squeeze=False)
    for ax, k in zip(axs[0], prim):
        c = pd.DataFrame(cm)
        c = c[(c.model == k[0]) & (c.featureset == k[1]) & (c.seed == k[2])].pivot(index="true", columns="predicted", values="count").reindex(index=C.CLASSES, columns=C.CLASSES)
        ax.imshow(np.log1p(c.values), cmap="Blues")
        for i in range(5):
            for j in range(5): ax.text(j, i, int(c.values[i, j]), ha="center", va="center", fontsize=7)
        ax.set_xticks(range(5), C.CLASSES, rotation=45, fontsize=7); ax.set_yticks(range(5), C.CLASSES, fontsize=7)
        ax.set(title=f"{k[0]}:{k[1]} seed {k[2]} ({sp}, n={n})", xlabel="Predicted", ylabel="True")
    C.savefig(fig, f"compare_confusion_{sp}")


if __name__ == "__main__":
    main()
